size_t group_size = binfo->group_size;
size_t nbits = binfo->nbits;
size_t group_idx = min_bit / group_size;
size_t bit_offset = min_bit % group_size;

while (group_idx < (nbits + group_size - 1) / group_size) {
    uint64_t group = bitmap[group_idx];

    // If the group is not all ones, there is an unset bit
    if (group != ~0ULL) {
        // Mask out bits before the starting offset for the first group
        if (group_idx == min_bit / group_size) {
            group |= ((1ULL << bit_offset) - 1);
        }

        // Find the first 0 bit. 
        // ~group flips 0s to 1s, then we find the first 1.
        uint64_t inverted = ~group;
        if (inverted != 0) {
            // __builtin_ctzll finds trailing zeros (index of first 1)
            size_t first_unset = __builtin_ctzll(inverted);
            size_t final_bit = group_idx * group_size + first_unset;
            return (final_bit < nbits) ? final_bit : nbits;
        }
    }
    group_idx++;
}

return nbits;
// END_CODE

